// build-search.mjs — emit the static full-text search index.
//
// Fumadocs' static client fetches /api/search. This script builds that JSON
// from the synced docs (src/content/docs/_synced/) at build time and writes it
// into the output directory, so search works with zero server endpoints — the
// site stays a fully static Cloudflare Pages deploy.
//
// Run from the `astro:build:done` hook in astro.config.mjs; the input tree is
// the same `_synced/` the content collections read (generated by sync-docs.ts).
import { readdir, readFile, writeFile, mkdir } from "node:fs/promises";
import { join, relative, resolve } from "node:path";
import { loader } from "fumadocs-core/source";
import { createFromSource } from "fumadocs-core/search/server";
import { structure } from "fumadocs-core/mdx-plugins";

const ROOT = resolve(import.meta.dirname, "..");
const SYNCED = join(ROOT, "src/content/docs/_synced");

async function walk(dir) {
  const out = [];
  let entries;
  try {
    entries = await readdir(dir, { withFileTypes: true });
  } catch {
    return out;
  }
  for (const ent of entries) {
    const abs = join(dir, ent.name);
    if (ent.isDirectory()) out.push(...(await walk(abs)));
    else out.push(abs);
  }
  return out;
}

/** Same shape as sync-docs.ts's parser — frontmatter block + body. */
function parseFrontmatter(raw) {
  if (!raw.startsWith("---\n")) return { body: raw, meta: {} };
  const end = raw.indexOf("\n---", 4);
  if (end === -1) return { body: raw, meta: {} };
  const block = raw.slice(4, end);
  const body = raw.slice(end + 4).replace(/^\n/, "");
  const meta = {};
  for (const line of block.split("\n")) {
    const m = line.match(/^([a-zA-Z0-9_-]+):\s*(.*)$/);
    if (m) meta[m[1]] = m[2].replace(/^"(.*)"\s*$/, "$1");
  }
  return { body, meta };
}

export async function buildSearchIndex(distDir) {
  const files = [];
  let pageCount = 0;

  for (const abs of await walk(SYNCED)) {
    const rel = relative(SYNCED, abs).split(/[\\/]/).join("/");
    if (abs.endsWith(".md")) {
      const raw = await readFile(abs, "utf8");
      const { body, meta } = parseFrontmatter(raw);
      files.push({
        type: "page",
        path: rel,
        data: {
          title: meta.title,
          description: meta.description || meta.summary,
          structuredData: structure(body),
        },
      });
      pageCount++;
    } else if (abs.endsWith("meta.json")) {
      files.push({
        type: "meta",
        path: rel,
        data: JSON.parse(await readFile(abs, "utf8")),
      });
    }
  }

  const source = loader({ source: { files }, baseUrl: "/" });
  const server = createFromSource(source);
  const exported = await server.export();

  await mkdir(join(distDir, "api"), { recursive: true });
  await writeFile(join(distDir, "api", "search.json"), JSON.stringify(exported), "utf8");
  console.log(`build-search: indexed ${pageCount} pages -> api/search.json`);
}
